window.AUTH=window.AUTH||{};window.AUTH["23-1270"]={"d":"23-1270","id":"2024/23-1270","n":"Riley v. Bondi","briefs":[{"k":"petitioner","label":"Brief of petitioner Pierre Riley","date":"2025-01-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-1270/336575/20250103170437724_Brief%20for%20Petitioner.pdf","side":"pet","n":81},{"k":"respondent","label":"Brief of respondent Merrick B. Garland, Attorney General in support of petitioner","date":"2025-01-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-1270/336571/20250103164128736_23-1270tsUnitedStates.pdf","side":"res","n":115},{"k":"reply","label":"Reply of petitioner Pierre Yassue Nashun Riley","date":"2025-03-14","url":"https://www.supremecourt.gov/DocketPDF/23/23-1270/352183/20250314155027985_Reply%20Brief%20for%20Petitioner.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us1r58_5h25.pdf","tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Adenariwo v. Federal Maritime Comm’n","cite":"808 F.3d 74","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/808/74/","by":{"0":"50"}},{"t":"case","label":"Alonso-Juarez v. Garland","cite":"80 F.4th 1039","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/80/1039/","op":2,"by":{"0":"18, 51, 52","1":"24, 35"}},{"t":"case","label":"American Hospital Assn. v. Becerra","cite":"596 U.S. 724","y":2022,"id":"2021/20-1114","sc":1,"op":1,"sum":"The Medicare Prescription Drug, Improvement, and Modernization Act of 2003 does not preclude judicial review of the reimbursement rates set by the Department of Health and Human Services for certain outpatient prescription drugs that hospitals provide to Medicare patients; in this case, because HHS did not conduct a survey of hospitals’ acquisition costs in 2018 and 2019, its decision to vary reimbursement rates only for 340B hospitals in those years was unlawful.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40"}},{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"op":3,"ar":3,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"17, 22, 24, 27","1":"23"}},{"t":"case","label":"Argueta-Hernandez v. Garland","cite":"87 F.4th 698","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/87/698/","op":3,"by":{"0":"41","1":"35"}},{"t":"case","label":"Army Corps of Engineers v. Hawkes Co.","cite":"578 U.S. 590","y":2016,"id":"2015/15-290","sc":1,"sum":"The Court determined that the Army Corps of Engineers’ jurisdictional determination that a property constituted “water of the United States” was a final agency action subject to judicial review under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Arostegui-Maldonado v. Garland","cite":"75 F.4th 1132","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/75/1132/","op":1,"by":{"0":"49"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Boechler, P.C. v. Commissioner of Internal Revenue","cite":"596 U.S. 199","y":2022,"id":"2021/20-1472","sc":1,"op":2,"sum":"The 30-day time limit to file a petition for review of a collection due process determination, 26 U. S. C. §6330(d)(1), is a nonjurisdictional deadline subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"17, 18, 26, 27","2":"1, 11"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"0":"25","1":"13, 19","2":"8, 9"}},{"t":"case","label":"Calcano-Martinez v. INS","cite":"533 U.S. 348","y":2001,"id":"2000/00-1011","sc":1,"sum":"The Court held that the Court of Appeals lacked jurisdiction to hear the petitions for direct but petitioners can proceed with their habeas petitions if they wish to obtain relief. \"As petitioners in this case were convicted of 'aggravated felonies' within the meaning of the relevant statutes,\" wrote Justice Stevens, \"the plain language of [IIRIRA] fairly explicitly strips the courts of appeals of jurisdiction to hear their claims on petitions for direct review.\" Justice Stevens continued that \"Congress has not spoken with sufficient clarity to strip the district courts of jurisdiction to hear habeas petitions raising identical claims.\".","sumSrc":"Oyez","by":{"0":"26","1":"2"}},{"t":"case","label":"Chicago & Southern Air Lines v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"0":"30, 34"}},{"t":"case","label":"Chupina v. Holder","cite":"570 F.3d 99","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/570/99/","by":{"0":"43","1":"38, 39"}},{"t":"case","label":"(iv) Cases—Continued Cyan v. Beaver County Employees Retirement Fund","cite":"583 U.S. 416","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/416/","sc":1,"by":{"0":"39"}},{"t":"case","label":"Delgado-Reynua v. Gonzales","cite":"450 F.3d 596","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/450/596/","by":{"0":"32"}},{"t":"case","label":"Eberhart v. United States","cite":"546 U.S. 12","y":2005,"id":"2005/04-9949","sc":1,"op":2,"sum":"The Court held that Federal Rule of Criminal Procedure 33, which creates a seven-day limit for filing a motion for a new trial that is not based on newly discovered evidence, was not a jurisdictional rule but rather a claim-processing one.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Eke v. Mukasey","cite":"512 F.3d 372","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/512/372/","by":{"0":"9","1":"41"}},{"t":"case","label":"F.J.A.P. v. Garland","cite":"94 F.4th 620","y":2024,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/94/620/","op":2,"by":{"0":"33, 42, 44, 50","1":"31, 33, 35, 37, 39, 48"}},{"t":"case","label":"Food Marketing Institute v. Argus Leader Media","cite":"588 U.S. 427","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28"}},{"t":"case","label":"Fort Bend County v. Davis","cite":"587 U.S. 541","y":2019,"id":"2018/18-525","sc":1,"sum":"The charge-filing precondition to suit set out in Title VII of the Civil Rights Act of 1964 is not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 21","1":"40"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Fritsch v. ICC","cite":"59 F.3d 248","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/59/248/","by":{"0":"50"}},{"t":"case","label":"Garland v. Cargill","cite":"602 U.S. 406","y":2024,"id":"2023/22-976","sc":1,"sum":"The Bureau of Alcohol, Tobacco, Firearms and Explosives exceeded its statutory authority by issuing a Rule that classifies a bump stock as a “machinegun” under 26 U. S. C. §5845(b).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"sum":"The Court held that a prisoner who does not seek review in a state’s highest court faces final judgment for the purposes of Section 2244(d)(1)(A) upon “expiration of the time for seeking such review.”","sumSrc":"Oyez","by":{"0":"20","1":"21"}},{"t":"case","label":"Grupo Dataflux v. Atlas Global Group, L.P.","cite":"541 U.S. 567","y":2004,"id":"2003/02-1689","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Court ruled that allowing diversity jurisdiction to change after a case is filed would create uncertainty and expensive litigation that dealt with jurisdiction rather than the merits of the case. \"Uncertainty regarding the question of jurisdiction is particularly undesirable, and collateral litigation on the point particularly wasteful,\" wrote Justice Scalia. \"The stability provided by our time tested rule (of requiring diversity at the time of filing) weighs heavily against the approval of any new deviation.\".","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"589 U.S. 221","y":2020,"id":"2019/18-776","sc":1,"op":4,"ar":1,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"0":"8, 36, 37, 40, 44, 52","1":"36, 38"}},{"t":"case","label":"Hall v. Hall","cite":"584 U.S. 59","y":2018,"id":"2017/16-1150","sc":1,"sum":"The Court decided that when one of multiple cases consolidated under FRCP 42(a) is finally decided, that ruling confers upon the losing party the right to immediate appeal regardless of whether any of the other consolidated cases are still pending.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Hall v. United States","cite":"566 U.S. 506","y":2012,"id":"2011/10-875","sc":1,"sum":"The Court held that assets sold by a debtor in bankruptcy proceedings does not count as a separately taxable estate in Chapter 12 bankruptcies.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Harrow v. Department of Defense","cite":"601 U.S. 480","y":2024,"id":"2023/23-21","sc":1,"op":3,"sum":"Title 5 U. S. C. §7703(b)(1)’s 60-day filing deadline for a federal employee to petition the Federal Circuit to review a final decision of the Merit Systems Protection Board is not jurisdictional.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18, 20, 21, 24, 25","1":"17-20, 22","2":"9, 10"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"op":7,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"18, 19, 23, 26","1":"19, 21"}},{"t":"case","label":"Inestroza-Tosta v. Attorney General","cite":"105 F.4th 499","y":2024,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/105/499/","sum":"Explaining that because the noncitizen there “did not get a final decision from the BIA until a year after his removal order was reinstated,” “[t]he promise of judicial review of agency action would be illusory for him”.","sumSrc":"brief:1","by":{"0":"21, 42","1":"37"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"op":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"8","1":"32"}},{"t":"case","label":"Janus v. State, County, and Municipal Employees","cite":"585 U.S. 878","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/878/","sc":1,"by":{"0":"25"}},{"t":"case","label":"Jean-Pierre v. U.S. Attorney General","cite":"500 F.3d 1315","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/500/1315/","by":{"0":"8"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"op":6,"ar":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"0":"22","2":"9, 10"}},{"t":"case","label":"Johnson v. Guzman Chavez","cite":"594 U.S. 523","y":2021,"id":"2020/19-897","sc":1,"op":15,"ar":7,"sum":"The detention of an alien ordered removed from the United States who reenters without authorization is governed by 8 U. S. C. §1231.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15, 16, 46, 47, 49–51","1":"6, 15, 16, 24, 37, 44-48","2":"13, 18, 19, 21"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"40, 44","1":"36","2":"24, 25"}},{"t":"case","label":"Lolong v. Gonzales","cite":"484 F.3d 1173","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/484/1173/","by":{"0":"32"}},{"t":"case","label":"Luna-Garcia v. Holder","cite":"777 F.3d 1182","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/1182/","by":{"0":"33","1":"41"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"op":4,"sum":"Holding that 28 U. S. C. § 2401(b), which provides that “[a] tort claim against the United States shall be forever barred unless it is Page Proof Pending Publication presented . . . within two years after such claim accrues,” is non-jurisdictional.","sumSrc":"opinion","by":{"0":"39"}},{"t":"case","label":"Martinez v. Garland","cite":"86 F.4th 561","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/86/561/","op":3,"by":{"0":"12, 43, 49","1":"10-12, 14, 28, 37, 38, 41, 43, 47, 48"}},{"t":"case","label":"Mohawk Industries, Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"sum":"The Court held that disclosure orders adverse to attorney-client privilege do not qualify for immediate appeal under the collateral order doctrine.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"op":1,"sum":"The Court found that distribution of small amounts of marijuana does not constitute an aggravated felony and thus, does not require deportation of the distributor.","sumSrc":"Oyez","by":{"0":"6, 40"}},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"sum":"The Court determined that the law of the case doctrine does not require that the sufficiency of evidence be measured against the elements laid out in the jury instructions when those elements require the government to prove more than the statute requires and the government did not object at trial. The Court also determined that a statute of limitations defense that is not raised at trial is not reviewable on appeal.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Nasrallah v. Barr","cite":"590 U.S. 573","y":2020,"id":"2019/18-1432","sc":1,"op":23,"ar":14,"sum":"The Court held that the federal courts have jurisdiction to review an administrative agency’s factual findings underlying denials of withholding (and deferral) of removal relief, notwithstanding 8 U.S.C. § 1252(a)(2)(C), which seems to divest courts of jurisdiction in such cases.","sumSrc":"Oyez","by":{"0":"3, 8, 9, 15, 28, 36, 41, 42, 44–46, 48, 52","1":"4, 6, 15, 24, 32, 34, 35, 40, 42-44, 47","2":"13"}},{"t":"case","label":"National Pork Producers Council v. Ross","cite":"598 U.S. 356","y":2023,"id":"2022/21-468","sc":1,"op":2,"sum":"Holding mandatory time bar non-jurisdictional.","sumSrc":"opinion","by":{"0":"45"}},{"t":"case","label":"Natural Resources Defense Council, Inc. v. NRC","cite":"680 F.2d 810","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/680/810/","by":{"0":"30"}},{"t":"case","label":"Neirbo Co. v. Bethlehem Shipbuilding Corp.","cite":"308 U.S. 165","y":1939,"id":"scdb/1939-030","sc":1,"sum":"1. Section 51 of the Judicial Code, as amended, which provides that \"no civil suit shall be brought in any district court against any person by any original process or proceeding in any other district than that whereof he is an inhabitant; but where the jurisdiction is founded only on the fact that the action is between citizens of different States, suit shall be brought only in the district of the residence of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Ogbudimkpa v. Ashcroft","cite":"342 F.3d 207","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/342/207/","by":{"0":"8"}},{"t":"case","label":"Owino v. Holder","cite":"575 F.3d 956","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/575/956/","by":{"0":"8"}},{"t":"case","label":"Port of Boston Marine Terminal Assn. v. Rederiaktiebolaget Transatlantic","cite":"400 U.S. 62","y":1970,"id":"1970/99","sc":1,"sum":"Petitioner Terminal Association, a maritime terminal operators conference. operating under an agreement approved by the Federal Maritime Commission (FMC), pursuant to §.15 of the Shipping Act, 1916, revised a tariff on file with the agency by shifting the incidence of a wharf demuri'age charge from consignees to carriers. When several carriers refused to pay the revised charge, which -had not previously been …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 31, 34","2":"3"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the IIRIRA deprives federal courts of jurisdiction over the selective-enforcement claim.","sumSrc":"Oyez","by":{"0":"7, 26","2":"10"}},{"t":"case","label":"Rodriguez-Roman v. INS","cite":"98 F.3d 416","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/98/416/","by":{"0":"41"}},{"t":"case","label":"Saint Fort v. Ashcroft","cite":"329 F.3d 191","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/329/191/","by":{"0":"8"}},{"t":"case","label":"Sanabria Morales v. Barr","cite":"967 F.3d 15","y":2020,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/967/15/","by":{"0":"43"}},{"t":"case","label":"Sandifer v. United States Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"op":4,"ar":9,"sum":"Holding mandatory time bar non-jurisdictional.","sumSrc":"opinion","by":{"0":"12, 13, 17, 18, 20, 21, 24, 25, 27, 52","1":"10, 13, 18, 21-23, 36","2":"7, 8, 12"}},{"t":"case","label":"Scarborough v. Principi","cite":"541 U.S. 401","y":2004,"id":"2003/02-1657","sc":1,"sum":"In a 7-to-2 opinion written by Justice Ruth Bader Ginsburg, the Court held that the statement on the application that the government's position had not been \"substantially justified\" was merely procedural. There was no need to prove the assertion - the applicant merely had to make the claim to shift the burden of proof to the government.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Sebelius v. Auburn Regional Medical Center","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"op":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"0":"20","1":"18"}},{"t":"case","label":"Smith v. Berryhill","cite":"587 U.S. 471","y":2019,"id":"2018/17-1606","sc":1,"op":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"30, 40","1":"30"}},{"t":"case","label":"Solano-Chicas v. Gonzales","cite":"440 F.3d 1050","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/440/1050/","by":{"0":"32"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"id":"2021/21-309","sc":1,"op":1,"sum":"Airplane cargo loaders and ramp supervisors who, like petitioner Saxon, frequently load and unload airplane cargo belong to a “class of workers engaged in foreign or interstate commerce” exempt from the Federal Arbitration Act’s coverage.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39, 50","2":"18"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"op":7,"ar":20,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 21, 22–27, 34, 35, 37, 38","1":"3, 10, 13, 17, 22, 23, 32","2":"1–9, 11, 12"}},{"t":"case","label":"Tadeo v. Garland","cite":"2024 WL 2780230","y":2024,"court":"5th Cir. May 30","by":{"0":"43"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"587 U.S. 554","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34, 35"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"op":5,"sum":"Holding that 28 U. S. C. § 2401(b), which provides that “[a] tort claim against the United States shall be forever barred unless it is Page Proof Pending Publication presented . . . within two years after such claim accrues,” is non-jurisdictional.","sumSrc":"opinion","by":{"0":"17, 19, 21","1":"18-21"}},{"t":"case","label":"Weyerhaeuser Co. v. United States Fish and Wildlife Serv.","cite":"586 U.S. 9","y":2018,"id":"2018/17-71","sc":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40"}},{"t":"case","label":"Whitman v. Am. Trucking Assns.","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Wilkins v. United States","cite":"598 U.S. 152","y":2023,"id":"2022/21-1164","sc":1,"op":3,"ar":1,"sum":"Holding mandatory time bar non-jurisdictional.","sumSrc":"opinion","by":{"0":"18, 22–24, 26","1":"19, 23","2":"2, 7, 8, 11"}},{"t":"case","label":"Zavaleta-Policiano v. Sessions","cite":"873 F.3d 241","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/873/241/","by":{"0":"41"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)","(a)(3)","(a)(47)(A)","(a)(47)(B)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"4","1":"2, 2, 3, 25, 26, 42, 4, 11, 14, 26-30, 39, 43","2":"16"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 1395oo","url":"https://www.law.cornell.edu/uscode/text/42/1395oo","by":{"0":"20"}},{"t":"law","label":"Foreign Affairs Reform and Restructuring Act, Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"0":"6, 8, 28, 40, 41","1":"5"}},{"t":"law","label":"Illegal Immigration Reform and Immigrant Responsibility Act, Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"6, 26, 34, 35, 37","1":"4"}},{"t":"law","label":"REAL ID Act, Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"0":"8","1":"8"}},{"t":"reg","label":"8 C.F.R. § 238.1","url":"https://www.ecfr.gov/current/title-8/section-238.1","subs":["(b)"],"by":{"0":"4"}},{"t":"reg","label":"64 Fed. Reg. 8,478","url":"https://www.govinfo.gov/link/fr/64/8478","by":{"0":"6"}},{"t":"case","label":"Barton v. Barr","cite":"590 U.S. 222","y":2020,"id":"2019/18-725","sc":1,"op":11,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"Bhaktibhai-Patel v. Garland","cite":"32 F.4th 180","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/32/180/","op":2,"by":{"1":"11, 28, 38, 41, 43, 47"}},{"t":"case","label":"Brownell v. Tom We Shung","cite":"352 U.S. 180","y":1956,"id":"1956/43","sc":1,"sum":"Under § 10 of the Administrative Procedure Act, an alien whose exclusion has been ordered administratively under the Immigration and Nationality Act of 1952, and who neither claims citizenship nor holds a certificate of identity issued under § 360 (b) of that Act, may obtain judicial review of such order by an action in a federal district court for a declaratory judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Clay v. United States","cite":"537 U.S. 522","y":2003,"id":"2002/01-1500","sc":1,"op":2,"sum":"The Court held that, for the purpose of starting the clock on section 2255's one-year limitation period, a judgment of conviction becomes final when the time expires for filing a petition for certiorari contesting the appellate court's affirmation of the conviction. Under this rule, Clay's section 2255 motion was timely filed.","sumSrc":"Oyez","by":{"1":"31, 33, 45"}},{"t":"case","label":"DHS v. Thuraissigiam","cite":"591 U.S. 103","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/103/","sc":1,"sum":"Describing Section 1229a proceedings as the “usual removal process”.","sumSrc":"brief:1","by":{"1":"26"}},{"t":"case","label":"Digital Equip. Corp. v. Desktop Direct, Inc.","cite":"511 U.S. 863","y":1994,"id":"1993/93-405","sc":1,"sum":"The Supreme Court ruled that the denial of immunity - while cause for concern - does not automatically create a right to immediate appeal. It is important to have final judgments before appeals are made, Justice David H. Souter wrote for the Court, and exceptions should only be made in particularly important cases.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"583 U.S. 149","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Environmental Def. v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"op":1,"sum":"Unanswered and No. In a unanimous opinion by Justice David Souter, the Court ruled that the EPA need not interpret \"modification\" in PSD regulations the same way the term is interpreted in NSPS regulations. The Court's opinion acknowledged that two occurrences of the same term - sharing the same definition - are normally given the same meaning.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"sum":"The Court ruled that the reinstatement statute does apply to illegal aliens who re-entered the U.S. before the effective date of the statute, and that the application to such aliens was not impermissibly retroactive.","sumSrc":"Oyez","by":{"1":"27, 28"}},{"t":"case","label":"Foti v. INS","cite":"375 U.S. 217","y":1963,"id":"1963/28","sc":1,"op":1,"sum":"Under § 106 (a) of the Immigration and Nationality Act, as added in 1961, a Federal Court of Appeals has sole and exclusive jurisdiction to review an administrative determination of the Attorney General denying a suspension of deportation sought by an alien under § 244 (a)(5). Pp. 217-232. 308 F.2d 779, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Gonzalez v. Chertoff","cite":"454 F.3d 813","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/454/813/","by":{"1":"28"}},{"t":"case","label":"Gutierrez de Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"sum":"Invoking the federal court's jurisdiction based on diversity of citizenship, petitioners alleged in their complaint that they had suffered physical injuries and property damage as a result of an accident in Colombia caused by the negligence of respondent Lamagno, a federal employee. The United States Attorney, acting pursuant to the statute commonly known as the Westfall Act, 28 U. S. C. §2679(d)(1), certified on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Hamer v. Neighborhood Hous. Servs.","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Heikkila v. Barber","cite":"345 U.S. 229","y":1953,"id":"scdb/1952-068","sc":1,"sum":"An alien whose deportation has been ordered by the Attorney General under § 19 (a) of the Immigration Act of 1917 may not obtain a review of the Attorney General's decision under § 10 of the Administrative Procedure Act, by a suit for a declaratory judgment or injunctive' relief.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"1":"5","2":"12"}},{"t":"case","label":"Jimenez-Morales v. U.S. Attorney Gen.","cite":"821 F.3d 1307","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/1307/","op":1,"by":{"1":"41"}},{"t":"case","label":"Kolov v. Garland","cite":"78 F.4th 911","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/78/911/","op":3,"by":{"1":"32, 38, 39, 46"}},{"t":"case","label":"Lawson v. Suwannee Fruit & S.S. Co.","cite":"336 U.S. 198","y":1949,"id":"scdb/1948-038","sc":1,"sum":"Under § 8 (f) (1) of the Act, the employer was liable only for permanent partial disability (loss of the left eye), and the remainder of the compensation due for permanent total disability was payable out of the special fund established by § 44 of the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"McLish v. Roff","cite":"141 U.S. 661","y":1891,"id":"scdb/1891-036","sc":1,"op":1,"sum":"Under section 5 of the Act of March 3, 1891, c. 517, 26 Stat..826, “ to establish Circuit Courts of Appeal,” etc., the appeal or writ of error which may be taken “ from the existing Circuit Courts direct to the Supreme Court,” “ in any case in which the jurisdiction of the court is in issue,’-’ can be taken only after final judgment; when the party against whom.it is rendered must elect whether he will take his writ …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"582 U.S. 23","y":2017,"id":"2016/15-457","sc":1,"sum":"The Court determined that the federal courts of appeals lack jurisdiction to review an order denying class certification after the named plaintiffs have voluntarily dismissed their claims with prejudice.","sumSrc":"Oyez","by":{"1":"31, 32, 35"}},{"t":"case","label":"Nielsen v. Preap","cite":"586 U.S. 392","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"2"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"586 U.S. 188","y":2019,"id":"2018/17-1094","sc":1,"sum":"Federal Rule of Civil Procedure 23(f), which establishes a 14-day deadline to seek permission to appeal an order granting or denying class certification, is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24","2":"5, 9"}},{"t":"case","label":"Ortiz-Alfaro v. Holder","cite":"694 F.3d 955","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/694/955/","by":{"1":"41"}},{"t":"case","label":"Osuna-Gutierrez v. Johnson","cite":"838 F.3d 1030","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/838/1030/","by":{"1":"28"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"op":2,"ar":1,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40"}},{"t":"case","label":"Ponce-Osorio v. Johnson","cite":"824 F.3d 502","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/824/502/","by":{"1":"41"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"1":"29, 30"}},{"t":"case","label":"Salgado v. Garland","cite":"69 F.4th 179","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/69/179/","by":{"1":"22, 23"}},{"t":"case","label":"Shaughnessy v. Pedreiro","cite":"349 U.S. 48","y":1955,"id":"scdb/1954-069","sc":1,"sum":"1. Under § 10 of the Administrative Procedure Act, an alien whose deportation has been ordered administratively under the Immigration and Nationality Act of 1952 may obtain a judicial review of such order by an action in a federal district court for a declaratory judgment and injunctive relief.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 45, 46"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"1":"14, 29, 30, 48","2":"16"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"13"}},{"t":"law","label":"Pub. L. No. 87-301","url":"https://www.govinfo.gov/link/statute/75/651","by":{"1":"3"}},{"t":"usc","label":"28 U.S.C. § 2341","url":"https://www.law.cornell.edu/uscode/text/28/2341","by":{"1":"3"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"1":"3"}},{"t":"usc","label":"8 U.S.C. § 1105a","url":"https://www.law.cornell.edu/uscode/text/8/1105a","subs":["(a)(1964)","(a)(1)(1964)","(a)(1)"],"by":{"1":"3, 3, 22, 23"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(h)"],"by":{"1":"40"}},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(e)"],"by":{"1":"40"}},{"t":"usc","label":"8 U.S.C. § 1228","url":"https://www.law.cornell.edu/uscode/text/8/1228","subs":["(b)","(b)(3)","(b)(5)","(c)"],"stext":{"head":"§1228. Expedited removal of aliens convicted of committing aggravated felonies","paras":[[0,"(a) Removal of criminal aliens"],[0,"(1) In general"],[1,"The Attorney General shall provide for the availability of special removal proceedings at certain Federal, State, and local correctional facilities for aliens convicted of any criminal offense covered in section 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to the date of their commission, otherwise covered by section 1227(a)(2)(A)(i) of this title. Such proceedings shall be conducted in conformity with section 1229a of this title (except as otherwise provided in this section), and in a manner which eliminates the need for additional detention at any processing center of the Service and in a manner which assures expeditious removal following the end of the alien's incarceration for the underlying sentence. Nothing in this section shall be construed to create any substantive or procedural right or benefit that is legally enforceable by any party against the United States or its agencies or officers or any other person."],[0,"(2) Implementation"],[1,"With respect to an alien convicted of an aggravated felony who is taken into custody by the Attorney General pursuant to section 1226(c) of this title, the Attorney General shall, to the maximum extent practicable, detain any such felon at a facility at which other such aliens are detained. In the selection of such facility, the Attorney General shall make reasonable efforts to ensure that the alien's access to counsel and right to counsel under section 1362 of this title are not impaired."],[0,"(3) Expedited proceedings"],[1,"(A) Notwithstanding any other provision of law, the Attorney General shall provide for the initiation and, to the extent possible, the completion of removal proceedings, and any administrative appeals thereof, in the case of any alien convicted of an aggravated felony before the alien's release from incarceration for the underlying aggravated felony."],[1,"(B) Nothing in this section shall be construed as requiring the Attorney General to effect the removal of any alien sentenced to actual incarceration, before release from the penitentiary or correctional institution where such alien is confined."],[0,"(4) Review"],[1,"(A) The Attorney General shall review and evaluate removal proceedings conducted under this section."],[1,"(B) The Comptroller General shall monitor, review, and evaluate removal proceedings conducted under this section. Within 18 months after the effective date of this section, the Comptroller General shall submit a report to such Committees concerning the extent to which removal proceedings conducted under this section may adversely affect the ability of such aliens to contest removal effectively."],[0,"(b) Removal of aliens who are not permanent residents"],[0,"(1) The Attorney General may, in the case of an alien described in paragraph (2), determine the deportability of such alien under section 1227(a)(2)(A)(iii) of this title (relating to conviction of an aggravated felony) and issue an order of removal pursuant to the procedures set forth in this subsection or section 1229a of this title."],[0,"(2) An alien is described in this paragraph if the alien—"],[1,"(A) was not lawfully admitted for permanent residence at the time at which proceedings under this section commenced; or"],[1,"(B) had permanent resident status on a conditional basis (as described in section 1186a of this title) at the time that proceedings under this section commenced."],[0,"(3) The Attorney General may not execute any order described in paragraph (1) until 14 calendar days have passed from the date that such order was issued, unless waived by the alien, in order that the alien has an opportunity to apply for judicial review under section 1252 of this title."],[0,"(4) Proceedings before the Attorney General under this subsection shall be in accordance with such regulations as the Attorney General shall prescribe. The Attorney General shall provide that—"],[1,"(A) the alien is given reasonable notice of the charges and of the opportunity described in subparagraph (C);"],[1,"(B) the alien shall have the privilege of being represented (at no expense to the government) by such counsel, authorized to practice in such proceedings, as the alien shall choose;"],[1,"(C) the alien has a reasonable opportunity to inspect the evidence and rebut the charges;"],[1,"(D) a determination is made for the record that the individual upon whom the notice for the proceeding under this section is served (either in person or by mail) is, in fact, the alien named in such notice;"],[1,"(E) a record is maintained for judicial review; and"],[1,"(F) the final order of removal is not adjudicated by the same person who issues the charges."],[0,"(5) No alien described in this section shall be eligible for any relief from removal that the Attorney General may grant in the Attorney General's discretion."],[0,"(c) 1 Presumption of deportability"],[0,"An alien convicted of an aggravated felony shall be conclusively presumed to be deportable from the United States."],[0,"(c) 1 Judicial removal"],[0,"(1) Authority"],[1,"Notwithstanding any other provision of this chapter, a United States district court shall have jurisdiction to enter a judicial order of removal at the time of sentencing against an alien who is deportable, if such an order has been requested by the United States Attorney with the concurrence of the Commissioner and if the court chooses to exercise such jurisdiction."],[0,"(2) Procedure"],[1,"(A) The United States Attorney shall file with the United States district court, and serve upon the defendant and the Service, prior to commencement of the trial or entry of a guilty plea a notice of intent to request judicial removal."],[1,"(B) Notwithstanding section 1252b 2 of this title, the United States Attorney, with the concurrence of the Commissioner, shall file at least 30 days prior to the date set for sentencing a charge containing factual allegations regarding the alienage of the defendant and identifying the crime or crimes which make the defendant deportable under section 1227(a)(2)(A) of this title."],[1,"(C) If the court determines that the defendant has presented substantial evidence to establish prima facie eligibility for relief from removal under this chapter, the Commissioner shall provide the court with a recommendation and report regarding the alien's eligibility for relief. The court shall either grant or deny the relief sought."],[1,"(D)(i) The alien shall have a reasonable opportunity to examine the evidence against him or her, to present evidence on his or her own behalf, and to cross-examine witnesses presented by the Government."],[1,"(ii) The court, for the purposes of determining whether to enter an order described in paragraph (1), shall only consider evidence that would be admissible in proceedings conducted pursuant to section 1229a of this title."],[1,"(iii) Nothing in this subsection shall limit the information a court of the United States may receive or consider for the purposes of imposing an appropriate sentence."],[1,"(iv) The court may order the alien removed if the Attorney General demonstrates that the alien is deportable under this chapter."],[0,"(3) Notice, appeal, and execution of judicial order of removal"],[1,"(A)(i) A judicial order of removal or denial of such order may be appealed by either party to the court of appeals for the circuit in which the district court is located."],[1,"(ii) Except as provided in clause (iii), such appeal shall be considered consistent with the requirements described in section 1252 of this title."],[1,"(iii) Upon execution by the defendant of a valid waiver of the right to appeal the conviction on which the order of removal is based, the expiration of the period described in section 1252(b)(1) of this title, or the final dismissal of an appeal from such conviction, the order of removal shall become final and shall be executed at the end of the prison term in accordance with the terms of the order. If the conviction is reversed on direct appeal, the order entered pursuant to this section shall be void."],[1,"(B) As soon as is practicable after entry of a judicial order of removal, the Commissioner shall provide the defendant with written notice of the order of removal, which shall designate the defendant's country of choice for removal and any alternate country pursuant to section 1253(a) 2 of this title."],[0,"(4) Denial of judicial order"],[1,"Denial of a request for a judicial order of removal shall not preclude the Attorney General from initiating removal proceedings pursuant to section 1229a of this title upon the same ground of deportability or upon any other ground of deportability provided under section 1227(a) of this title."],[0,"(5) Stipulated judicial order of removal"],[1,"The United States Attorney, with the concurrence of the Commissioner, may, pursuant to Federal Rule of Criminal Procedure 11, enter into a plea agreement which calls for the alien, who is deportable under this chapter, to waive the right to notice and a hearing under this section, and stipulate to the entry of a judicial order of removal from the United States as a condition of the plea agreement or as a condition of probation or supervised release, or both. The United States district court, in both felony and misdemeanor cases, and a United States magistrate judge in misdemeanor cases, may accept such a stipulation and shall have jurisdiction to enter a judicial order of removal pursuant to the terms of such stipulation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1228?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":2,"head":"§1228. Expedited removal of aliens convicted of committing aggravated felonies","tname":"Aliens and Nationality","by":{"1":"6-8, 12, 14-16, 24-30, 32, 7, 26, 6, 6"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(a)(1)"],"by":{"1":"26, 30, 32, 38, 43, 26"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","by":{"1":"40"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(a)","(a)(1)","(a)(1)(B)(i)","(a)(2)","(a)(5)","(b)(1)","(b)(2)","(b)(3)","(b)(3)(B)","(b)(3)(C)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":4,"head":"§1231. Detention and removal of aliens ordered removed","tname":"Aliens and Nationality","by":{"1":"45-47, 16, 45, 46, 16, 44, 46, 47, 6, 7, 10, 11, 14, 15, 27, 28, 37, 39-41, 44, 5, 5, 5, 9, 34"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)","(a)(2)","(a)(2)(C)","(a)(4)","(b)","(b)(1)","(b)(2)","(b)(3)(A)","(b)(3)(C)","(b)(4)","(b)(6)","(b)(9)","(d)(1)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":15,"ar":3,"sum":"Stating that the fling of “a petition for review fled with an appropriate court of appeals in accordance with [§ 1252]” is the “sole and exclusive means for judicial review” of any CAT claim.","sumSrc":"opinion","head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"1":"4, 8, 31, 36, 45, 47, 48, 2, 4, 31, 40, 42, 43, 8, 34, 40, 43, 21, 2, 4, 10-17, 20-26, 30, 32, 34-37, 39, 40, 42-46, 48, 21, 21, 22, 34, 40, 32, 4, 15, 31, 32, 34, 43, 46, 23, 32, 27"}},{"t":"usc","label":"8 U.S.C. § 1252a","url":"https://www.law.cornell.edu/uscode/text/8/1252a","subs":["(a)(3)(A)(1994)"],"by":{"1":"27"}},{"t":"usc","label":"8 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/8/1253","subs":["(a)(1)","(a)(1)(B)"],"by":{"1":"34, 34"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(b)(1)"],"stext":{"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","paras":[[0,"(a)(1) Any employee or applicant for employment adversely affected or aggrieved by a final order or decision of the Merit Systems Protection Board may obtain judicial review of the order or decision."],[0,"(2) The Board shall be named respondent in any proceeding brought pursuant to this subsection, unless the employee or applicant for employment seeks review of a final order or decision on the merits on the underlying personnel action or on a request for attorney fees, in which case the agency responsible for taking the personnel action shall be the respondent."],[0,"(b)(1)(A) Except as provided in subparagraph (B) and paragraph (2) of this subsection, a petition to review a final order or final decision of the Board shall be filed in the United States Court of Appeals for the Federal Circuit. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(B) A petition to review a final order or final decision of the Board that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D) shall be filed in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(2) Cases of discrimination subject to the provisions of section 7702 of this title shall be filed under section 717(c) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16(c)), section 15(c) of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 633a(c)), and section 16(b) of the Fair Labor Standards Act of 1938, as amended (29 U.S.C. 216(b)), as applicable. Notwithstanding any other provision of law, any such case filed under any such section must be filed within 30 days after the date the individual filing the case received notice of the judicially reviewable action under such section 7702."],[0,"(c) In any case filed in the United States Court of Appeals for the Federal Circuit, the court shall review the record and hold unlawful and set aside any agency action, findings, or conclusions found to be—"],[1,"(1) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(2) obtained without procedures required by law, rule, or regulation having been followed; or"],[1,"(3) unsupported by substantial evidence;"],[0,"except that in the case of discrimination brought under any section referred to in subsection (b)(2) of this section, the employee or applicant shall have the right to have the facts subject to trial de novo by the reviewing court."],[0,"(d)(1) Except as provided under paragraph (2), this paragraph shall apply to any review obtained by the Director of the Office of Personnel Management. The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the Court of Appeals. The granting of the petition for judicial review shall be at the discretion of the Court of Appeals."],[0,"(2) This paragraph shall apply to any review obtained by the Director of the Office of Personnel Management that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D). The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the court of appeals. The granting of the petition for judicial review shall be at the discretion of the court of appeals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7703?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","tname":"Government Organization and Employees","by":{"1":"18"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(b)"],"stext":{"head":"§2401. Time for commencing action against United States","paras":[[0,"(a) Except as provided by chapter 71 of title 41, every civil action commenced against the United States shall be barred unless the complaint is filed within six years after the right of action first accrues. The action of any person under legal disability or beyond the seas at the time the claim accrues may be commenced within three years after the disability ceases."],[0,"(b) A tort claim against the United States shall be forever barred unless it is presented in writing to the appropriate Federal agency within two years after such claim accrues or unless action is begun within six months after the date of mailing, by certified or registered mail, of notice of final denial of the claim by the agency to which it was presented."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2401?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2401. Time for commencing action against United States","tname":"Judiciary and Judicial Procedure","by":{"1":"19"}},{"t":"usc","label":"28 U.S.C. § 2409a","url":"https://www.law.cornell.edu/uscode/text/28/2409a","subs":["(g)"],"by":{"1":"19"}},{"t":"usc","label":"38 U.S.C. § 7266","url":"https://www.law.cornell.edu/uscode/text/38/7266","subs":["(a)"],"stext":{"head":"§7266. Notice of appeal","paras":[[0,"(a) In order to obtain review by the Court of Appeals for Veterans Claims of a final decision of the Board of Veterans' Appeals, a person adversely affected by such decision shall file a notice of appeal with the Court within 120 days after the date on which notice of the decision is issued pursuant to section 7104(e) of this title."],[0,"(b) An appellant shall file a notice of appeal under this section by delivering or mailing the notice to the Court."],[0,"(c) A notice of appeal shall be deemed to be received by the Court as follows:"],[1,"(1) On the date of receipt by the Court, if the notice is delivered."],[1,"(2) On the date of the United States Postal Service postmark stamped on the cover in which the notice is posted, if the notice is properly addressed to the Court and is mailed."],[0,"(d) For a notice of appeal mailed to the Court to be deemed to be received under subsection (c)(2) on a particular date, the United States Postal Service postmark on the cover in which the notice is posted must be legible. The Court shall determine the legibility of any such postmark and the Court's determination as to legibility shall be final and not subject to review by any other Court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7266?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7266. Notice of appeal","tname":"Veterans' Benefits","by":{"1":"19"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(d)"],"by":{"1":"32"}},{"t":"case","label":"Arkansas Game & Fish Comm’n v. United States","cite":"568 U.S. 23","y":2012,"id":"2012/11-597","sc":1,"sum":"The Court held the Fifth Amendment's Taking Clause could be enacted when a temporary flood regime destroyed property.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Cohens v. Virginia","cite":"6 Wheat. 264","y":1821,"url":"https://www.courtlistener.com/c/Wheat./6/264/","by":{"2":"6"}},{"t":"case","label":"Fourco Glass Co. v. Transmirra Products Corp.","cite":"353 U.S. 222","y":1957,"id":"1956/310","sc":1,"sum":"1. Venue in patent infringement actions is governed exclusively by 28 U. S. C. § 1400 (b), which provides that any such action may be brought \"in the judicial district where the defendant resides, or where the defendant has committed acts of infringement and has a regular and established place of business\"; and 28 U. S. C. § 1391 (c) has no application to such actions. Stonite Products Co. v. Melvin Lloyd Co., 315 …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Fulton v. Philadelphia","cite":"593 U.S. 522","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/522/","sc":1,"by":{"2":"16"}},{"t":"case","label":"Goldman Sachs Group, Inc. v. Arkansas Teachers Retirement System","cite":"594 U.S. 113","y":2021,"id":"2020/20-222","sc":1,"op":5,"sum":"The generic nature of a misrepresentation in connection with the sale of securities often is important evidence of price impact that courts should consider at class certification; defendants bear the burden of persuasion to prove a lack of price impact by a preponderance of the evidence at class certification.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"ICC v. Locomotive Engineers","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"op":2,"sum":"In October 1982, petitioner Interstate Commerce Commission (ICC or Commission) issued an order, which, inter alia, granted petitioner Missouri-Kansas-Texas Railroad Co. and another railroad the right to conduct operations using the tracks of a third, newly consolidated carrier. In April 1983, respondent Brotherhood of Locomotive Engineers (BLE) filed a \"Petition for Clarification\" asking the ICC to declare that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4, 5, 19"}},{"t":"case","label":"(iii) Cases—Continued Kimble v. Marvel Entertainment, LLC","cite":"576 U.S. 446","y":2015,"url":"https://supreme.justia.com/cases/federal/us/576/446/","sc":1,"by":{"2":"11"}},{"t":"case","label":"Knick v. Township of Scott","cite":"588 U.S. 180","y":2019,"id":"2018/17-647","sc":1,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"12"}},{"t":"case","label":"Missouri v. Jenkins","cite":"495 U.S. 33","y":1990,"id":"1989/88-1150","sc":1,"sum":"The Court held that the District Court \"abused its discretion\" by imposing a specific tax increase.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Pace v. DiGuglielmo","cite":"544 U.S. 408","y":2005,"id":"2004/03-9627","sc":1,"sum":"The Court held that the federal statute of limitations barred Pace's petition, as it was filed beyond the deadline. Pace was not entitled to statutory tolling because a petition filed after a time limit, which does meet any exceptions to that limit, was no more \"properly filed\" than a petition filed after a time limit permitting no exception.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2020,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"TikTok Inc. v. Garland","cite":"145 S. Ct. 57","y":2025,"id":"2024/24-656","sc":1,"sum":"The challenged provisions of the Protecting Americans from Foreign Adversary Controlled Applications Act, 138 Stat. 955, do not violate petitioners’ First Amendment rights.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"15"}},{"t":"case","label":"United States v. Dieter","cite":"429 U.S. 6","y":1976,"id":"1976/75-1547","sc":1,"sum":"The 30-day limitation period prescribed by the Criminal Appeals Act and Fed. Rule App. Proc. 4 (b) for a Government appeal from an order dismissing an indictment ran from the date of the District Court's denial of the Government's motion to set aside the dismissal of the indictment against respondent, rather than from the date of the dismissal order, and hence the Government's appeal was timely where its notice of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"United States v. Ibarra","cite":"502 U.S. 1","y":1991,"id":"1991/90-1713","sc":1,"sum":"The Government's appeal was timely. All motions for reconsideration are subsumed under one general rule-the rule laid down in Healy. If a merits inquiry were grafted onto the general rule, litigants would 1 UNITED STATES v. IBARRA","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"2":"21"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"2":"12"}},{"t":"reg","label":"8 C.F.R. § 208.5","url":"https://www.ecfr.gov/current/title-8/section-208.5","subs":["(a)"],"by":{"2":"15"}}]};